                    novel.tags2 = novel.tags2.concat(tags)
                } else {
                    novel.tags2.push(tag)
                }
            }
            novel.tags = Array.from(new Set(novel.tags2))
            novel.tags = novel.tags.map(item => `#${item}`)
            novel.tags = novel.tags.join(",")

            if (util.settings.MORE_INFORMATION) {
