{"content":"<js>

var b64Match = src.match(/qTcms_S_m_murl_e="([^"]*)"/);
var idMatch = src.match(/qTcms_m_url="\/manhua\/(\d+)\/"/);




let options = {
    "headers": {
        'User-Agent': "Mozilla/5.0 (Linux; Android 13; PFJM10 Build/TP1A.220905.001; wv) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/132.0.6834.163 Mobile Safari/537.36",
        'referer': "https://www.veryim.com/"
    }
};

if (b64Match&&idMatch) {
    var b64 = java.base64Decode(b64Match[1]);

     var id = idMatch[1]

    var imgMatches = b64.match(/(https?:\/\/[^$]+)(\$qingtiandy\$|$)/g);

    if (imgMatches) {
        var imgArray = imgMatches.map(function(match) {
            return match.split('$qingtiandy$')[0]; 
        });

        var uniqueImgArray = Array.from(new Set(imgArray));

        var data = JSON.stringify(uniqueImgArray);

        var html = uniqueImgArray.map(function(img) {
            return '<img src="https://c3.imgsss.com/statics/pic/?p='+ img + "&picid=" + id+","+JSON.stringify(options)+'">'; 
        }).join('');


        html;
    } else {
        java.log("未找到图片链接");
    }
} else {
    java.log("未找到 Base64 编码的字符串");
}



</js>"}

