    if (resp.novels) {
        return seriesHandler(resp)
    } else if (resp.series) {
        // 优化 未缓存系列目录的情况
        return seriesContentHandler(resp)
    } else {
        return oneShotHandler(resp)
    }
})()","chapterName":"title","chapterUrl":"chapterUrl","updateTime":"chapterInfo"}

