    );
  eval(paramJs);
  h = String(java.getString("id." + java.get("id") + "@html"));
  h = h.replace("&nbsp;&nbsp;", "&emsp;");
  const acontentTarget = {
    innerHTML: String(h),
    get childNodes() {
      const tagRegex = /<p>.*?<\/p>|<img[^>]*>/g;
      const matchedTags = this.innerHTML.match(tagRegex) || [];

      return matchedTags
        .map((outerHTML) => {
          if (outerHTML.startsWith("<p>")) {
            return createParagraphProxy(outerHTML);
          }

          if (outerHTML.startsWith("<img")) {
            return createMockElement(
              "IMG",
              {
