      {
        appendChild(element) {
          // java.log("head appendChild", element);
        },
      },
      "head"
    ),
  };

  // 获取空行索引
  var tagRegex;
  tagRegex = /<p>.*?<\/p>|<img[^>]*>|<br>/g;
  const matchedTags = acontentTarget.innerHTML.match(tagRegex) || [];
  const blankLines = matchedTags
    .map((element, index) => (element === "<br>" ? index : -1)) // 匹配返回索引，否则返回 -1
    .filter((index) => index !== -1); // 过滤掉 -1

  // 全局 document 对象
