      html = '<p>' + item.text + createBubble(item.comment_count, item.comment_url, bubble) + '</p>';
    } else {
      html = item.text;
    }
    if (item.image) {
      if (typeof item.image === 'string') {
        html += '<img src="' + item.image + '">';
      } else if (Array.isArray(item.image)) {
        for (var j = 0; j < item.image.length; j++) {
          html += '<img src="' + item.image[j] + '">';
        }
      }
    }

    contents.push(html);
  }

  content = contents.join("\n");

  if (enabledChapter&&chapterSvgs!="") {
  	    let chapterUrl = result.data.comment.chapter_card.url
